// Behavior depends on operand type (promoted to int or unsigned int)

// Unsigned: Guaranteed Logical Shift (Zero Fill)
unsigned char u = 0xF0; // 1111 0000
u << 1;                 // Left Shift (Multiply by 2)
u >> 4;                 // 0000 1111 (Zero fill)

// Signed: Right Shift is implementation defined (Arithmetic common)
int s = -16;
s >> 2;                 // Usually -4 (Sign preserved/propagated)

// Constraints & Undefined Behavior (UB)
// s << 32;              // UB if shift amount >= bits in type
// int x = 1;
// x << 31;              // UB if result overflows (sign bit changes)
